#include "engine.hpp"
#include <iostream>
using namespace uaa;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
void arrive(Engine& e){double at=e.state["tradeFlights"].back()["arrival"];e.advance(at-e.state["hours"].get<double>());}
int main(int argc,char** argv){try{check(argc==3,"Expected data and directory");Engine e(argv[1],argv[2]);e.createBase("FREIGHT",50,14);e.state["nextUfo"]=100000.;int initial=e.state["stock"]["pistol"];auto money=e.state["money"].get<long long>();check(e.trade("weapons","pistol",true,100,0,"Germany").ok,"Book a real cargo import");check(e.state["stock"]["pistol"]==initial&&e.state["money"].get<long long>()==money-65000,"Purchase pays once and does not teleport goods into storage");auto f=e.freightStatus(0);check(f["partner"]=="Germany"&&f["hoursLeft"].get<double>()>0,"Flight records supplier country and positive ETA");e.advance(f["hoursLeft"].get<double>()/2);check(e.state["stock"]["pistol"]==initial&&e.freightStatus(0)["progress"].get<double>()>0,"Goods remain unavailable during flight");e.save(1);Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok&&loaded.state["tradeFlights"]==e.state["tradeFlights"],"In-flight delivery survives reload");arrive(e);check(e.state["stock"]["pistol"]==initial+100&&e.state["tradeFlights"][0]["delivered"]==true,"Arrival delivers full quantity once");e.advance(1);check(e.state["stock"]["pistol"]==initial+100,"Goods are not delivered twice");money=e.state["money"];check(e.trade("weapons","pistol",false,100,0,"Japan").ok&&e.state["stock"]["pistol"]==initial&&e.state["money"]==money,"Sale removes the exported cargo but does not pay before arrival");arrive(e);check(e.state["money"].get<long long>()==money+32500,"Buyer-country arrival settles sale proceeds");
 auto& buildings=e.state["bases"][0]["buildings"];for(auto& b:buildings)if(b["id"]=="runway")b["ready"]=e.state["hours"].get<double>()+10;auto before=e.state;check(!e.trade("weapons","pistol",true).ok&&!e.trade("weapons","pistol",false).ok&&e.state==before,"Unfinished airport blocks both directions atomically");e.advance(10);check(e.trade("units","underwater-robot",true,1,0,"France").ok&&e.state["stock"].value("underwater-robot",0)==0,"Optional underwater robot uses the same cargo aircraft procurement");for(auto& b:buildings)if(b["id"]=="runway")b["ready"]=e.state["hours"].get<double>()+100;arrive(e);check(e.state["tradeFlights"].back()["status"]=="awaitingAirport"&&e.state["stock"].value("underwater-robot",0)==0,"If airport becomes unavailable the arriving aircraft holds its cargo");e.advance(100);check(e.state["stock"]["underwater-robot"]==1,"Cargo delivers when airport is restored");
 e.state["money"]=1000000000LL;check(e.trade("units","underwater-robot",true,100).ok,"Book a large delivery");arrive(e);check(e.state["tradeFlights"].back()["status"]=="awaitingStorage","Oversized deliveries wait rather than overflow storage");check(e.createBase("NO AIRPORT",-20,-40).ok,"Create a second base");e.state["bases"][1]["buildings"].push_back({{"id","storage"},{"x",0},{"y",0},{"floor",0},{"ready",0.}});before=e.state;check(!e.trade("materials","iron",true,1,1,"Germany").ok&&e.state==before,"An airport at another base does not authorize trade at this destination");
 Engine loss(argv[1],std::filesystem::path(argv[2])/"loss");loss.createBase("LOSS",50,14);loss.state["nextUfo"]=100000.;int stock=loss.state["stock"]["pistol"];check(loss.trade("weapons","pistol",true,3).ok,"Book doomed import");auto paid=loss.state["money"];check(loss.damageFreight(0,100).ok,"Shoot down incoming aircraft");loss.advance(48);check(loss.state["stock"]["pistol"]==stock&&loss.state["money"]==paid&&loss.state["tradeFlights"][0]["status"]=="destroyed","Destroyed import never delivers or refunds");check(loss.trade("weapons","pistol",false,1).ok,"Book doomed export");check(loss.damageFreight(1,100).ok,"Shoot down outbound aircraft");loss.advance(48);check(loss.state["stock"]["pistol"]==stock-1&&loss.state["money"]==paid,"Destroyed export never restores goods or pays proceeds");loss.save(1);Engine restored(argv[1],std::filesystem::path(argv[2])/"loss");check(restored.load(1).ok&&restored.state["tradeFlights"]==loss.state["tradeFlights"],"Lost freight persists without compensation");check(!e.damageFreight(0,100).ok,"Completed delivery cannot be destroyed retroactively");
 Engine hostile(argv[1],std::filesystem::path(argv[2])/"hostile");hostile.createBase("THREAT",50,14);hostile.state["nextUfo"]=100000.;check(hostile.trade("weapons","pistol",true,1).ok,"Book intercepted import");auto pos=hostile.freightStatus(0,.25);for(int i=0;i<30;++i)hostile.state["ufos"].push_back({{"type","UNMANNED_DRONE"},{"lat",pos["lat"]},{"lon",pos["lon"]},{"hull",100.},{"spawned",0.},{"expires",720.},{"environment","AIR"}});hostile.rng.seed(1);hostile.advance(.25);check(hostile.state["tradeFlights"][0]["status"]=="destroyed","Real nearby airborne UFOs can shoot cargo aircraft down during campaign time");
 auto broken=readJson(e.userDir/"save-1.json");broken["tradeFlights"][0]["quantity"]=-1;writeJson(e.userDir/"save-2.json",broken);before=loaded.state;check(!loaded.load(2).ok&&loaded.state==before,"Malformed logistics are rejected transactionally");check(e.tradePartners().size()>50,"Trading partners come from the existing game states");std::cout<<"PASS: country cargo flights, delayed stock/payment, ETA/progress, one-time arrival, exact-base airport gate, construction, holding, capacity, optional robot, save/load validation\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
